class Solution {
    long long power(long long base, long long exp, long long mod) {
        long long result = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
public:
    vector<int> productQueries(int n, vector<vector<int>>& queries) {
        const int MOD = 1e9 + 7;

        vector<long long> powers;
        for (int i = 0; i < 31; i++) {
            if (n & (1LL << i)) {
                powers.push_back(1LL << i);
            }
        }

        int k = powers.size();

        vector<long long> prefix(k + 1);
        prefix[0] = 1;
        for (int i = 0; i < k; i++) {
            prefix[i + 1] = prefix[i] * powers[i] % MOD;
        }

        int m = k + 1;
        vector<long long> pre(m), invPre(m), invPrefix(m);

        pre[0] = prefix[0];
        for (int i = 1; i < m; i++) {
            pre[i] = pre[i - 1] * prefix[i] % MOD;
        }

        invPre[m - 1] = power(pre[m - 1], MOD - 2, MOD);
        for (int i = m - 1; i >= 1; i--) {
            invPre[i - 1] = invPre[i] * prefix[i] % MOD;
        }

        for (int i = 0; i < m; i++) {
            invPrefix[i] = invPre[i] * (i > 0 ? pre[i - 1] : 1LL) % MOD;
        }

        vector<int> answers;
        answers.reserve(queries.size());
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            long long ans = prefix[r + 1] * invPrefix[l] % MOD;
            answers.push_back((int)ans);
        }

        return answers;
    }
};
